import type { Valid } from "../Validated";
import type { NonEmptyArray } from "../Types";
/**
 * A passthrough validator that just returns the value
 * passed in as a {@link Valid} object with that value.
 *
 * @param value The value to be wrapped by a {@link Valid} instance.
 * @internal
 */
export declare const asAny: <T, E = unknown>(value: T) => Valid<T, NonEmptyArray<E>>;
